import Foundation

enum GameLibrary {
    static let games: [Game] = [
        Game(title: "Red Dead Redemption 2", subtitle: "Rockstar Games · 2018", imageName: "rdr2", rating: 5,
            description: "Set in 1899, you play Arthur Morgan, an outlaw whose gang is running out of road as the age of the Wild West ends. The open world is full of small stories: hunting, camping, poker nights and chance meetings that feel alive. The slow pace and the weight of every choice make it the most emotional game I have played."),
        Game(title: "The Witcher 3: Wild Hunt", subtitle: "CD Projekt Red · 2015", imageName: "witcher3", rating: 5,
            description: "You are Geralt of Rivia, a monster hunter searching for his adopted daughter across a huge war-torn continent. Even the side quests feel like short novels, with morally grey choices and real consequences. The Blood and Wine expansion alone is bigger than most full games."),
        Game(title: "Cyberpunk 2077", subtitle: "CD Projekt Red · 2020", imageName: "cyberpunk2077", rating: 4,
            description: "Night City is a neon-soaked megacity where V chases immortality with a dead rockstar living inside their head. The launch was rough, but patches and the Phantom Liberty expansion turned it into a great game. The story, the music and the city itself are unforgettable."),
        Game(title: "Grand Theft Auto V", subtitle: "Rockstar Games · 2013", imageName: "gta5", rating: 5,
            description: "Three criminals, Michael, Franklin and Trevor, pull heists across a sun-soaked Los Santos. Switching between them at any moment keeps the story fresh and funny. Years after release, GTA Online still gives me a reason to come back with friends."),
        Game(title: "Grand Theft Auto VI", subtitle: "Rockstar Games · 2026", imageName: "gta6", rating: 0,
            description: "The next Rockstar game returns to Vice City and brings the first female lead of the series. I have only seen the trailers, but they already broke every record on the internet. I am rating it zero for now because I am still waiting to play it."),
        Game(title: "Disco Elysium", subtitle: "ZA/UM · 2019", imageName: "discoelysium", rating: 5,
            description: "You wake up as an amnesiac detective with a hangover, a missing badge and a murder to solve. There is almost no combat, so every fight happens inside your head between competing skills and ideologies. The writing is sharp, bleak and funny at the same time, and I still quote it."),
        Game(title: "Europa Universalis IV", subtitle: "Paradox Development Studio · 2013", imageName: "eu4", rating: 4,
            description: "Europa Universalis IV is a grand strategy game where you guide a nation from 1444 to 1821. You manage diplomacy, trade, wars and religion, and no two campaigns look the same. It has a steep learning curve, but few games let you rewrite history this deeply."),
        Game(title: "Stardew Valley", subtitle: "ConcernedApe · 2016", imageName: "stardewvalley", rating: 4,
            description: "You inherit a rundown farm and slowly turn it into a home, growing crops, raising animals and getting to know the villagers. There is no pressure, so you can play at your own pace and just relax. The soundtrack and the pixel art make every season feel cozy."),
        Game(title: "Elden Ring", subtitle: "FromSoftware · 2022", imageName: "eldenring", rating: 5,
            description: "FromSoftware and George R. R. Martin built a vast open world full of ruins, dragons and secrets in the Lands Between. Bosses are brutal, but exploring freely and finding a new path around a hard fight is very rewarding. Every victory feels earned."),
        Game(title: "Alan Wake 2", subtitle: "Remedy Entertainment · 2023", imageName: "alanwake2", rating: 4,
            description: "A horror writer is trapped in a nightmare version of reality while an FBI agent investigates a ritual murder in a small town. The game switches between two playable heroes and mixes live action with a twisting, meta story. It is atmospheric, tense and beautifully made."),
        Game(title: "Kingdom Come: Deliverance", subtitle: "Warhorse Studios · 2018", imageName: "kcd", rating: 4,
            description: "Kingdom Come: Deliverance puts you in 15th century Bohemia as Henry, a blacksmith's son who survives the destruction of his village. There is no magic here, only historically accurate swords, armor and politics. Combat is slow and difficult, which makes it feel grounded."),
        Game(title: "Kingdom Come: Deliverance II", subtitle: "Warhorse Studios · 2025", imageName: "kcd2", rating: 5,
            description: "The sequel follows Henry as the war for Bohemia grows bigger and more dangerous. The world is richer, the quests are more varied, and the combat and stealth are much more polished. It is a rare sequel that improves on its predecessor in nearly every way."),
        Game(title: "Control", subtitle: "Remedy Entertainment · 2019", imageName: "control", rating: 4,
            description: "Jesse Faden arrives at the Federal Bureau of Control and becomes the new Director of a building that constantly rearranges itself. Telekinetic powers make every fight feel like a superhero action movie. The weird, brutalist setting reminds me of a David Lynch film."),
        Game(title: "Subnautica", subtitle: "Unknown Worlds Entertainment · 2018", imageName: "subnautica", rating: 4,
            description: "After your spaceship crashes on an alien ocean planet, you must gather resources, build bases and survive underwater. Exploring deeper and deeper becomes both thrilling and terrifying. I will never forget the first time I saw a Reaper Leviathan."),
        Game(title: "Hotline Miami", subtitle: "Dennaton Games · 2012", imageName: "hotlinemiami", rating: 3,
            description: "Hotline Miami is a fast, violent top-down action game set in 1989 Miami with a wild synthwave soundtrack. You die in one hit, so every room is a quick puzzle that you replay until it is perfect. The strange story leaves you with more questions than answers."),
        Game(title: "Undertale", subtitle: "Toby Fox · 2015", imageName: "undertale", rating: 4,
            description: "In Undertale you fall into the underground world of monsters, and every fight can be won without killing anyone. Your choices change the story, the characters and even the ending. It is funny, sad and surprising, with a soundtrack that I still listen to."),
        Game(title: "The Elder Scrolls V: Skyrim", subtitle: "Bethesda Game Studios · 2011", imageName: "skyrim", rating: 4,
            description: "You are the Dragonborn, a hero who can absorb the souls of dragons and use their shouts. The mountains of Skyrim are full of caves, guilds and quests that you can follow in any order. Thanks to mods, it is still fun more than a decade later."),
        Game(title: "The Last of Us", subtitle: "Naughty Dog · 2013", imageName: "tlou", rating: 5,
            description: "Joel and Ellie travel across a post-apocalyptic America overrun by infected, and their bond is the heart of the story. Resources are scarce, so every bullet and every fight matters. The ending is one of the most discussed in video game history."),
        Game(title: "Detroit: Become Human", subtitle: "Quantic Dream · 2018", imageName: "detroit", rating: 4,
            description: "In a near-future Detroit, you control three androids who start to question their purpose and feel emotions. Almost every scene branches, so your decisions decide who lives, who dies and how the world sees androids. It plays like an interactive movie with a lot of replay value."),
        Game(title: "Batman: Arkham Knight", subtitle: "Rocksteady Studios · 2015", imageName: "batmanak", rating: 3,
            description: "In the final chapter of the Arkham trilogy, Batman protects Gotham from the Scarecrow and a mysterious Arkham Knight. Gliding over the city and driving the Batmobile feel great. The combat is satisfying, although the tank battles are repetitive.")
    ]
